        item = delay_queue.select_next_some() => {
           // The fused `DelayQueue` closed and this code will never called (
        }
        event_to_schedule = some_channel.select_next_some() => {
            delay_queue.get_mut().insert_at(event_to_schedule.item, event_to_schedule.instant);
        }
    }
}
