Calling `ClientRequest.destroy(new Error(...))` from a timeout handler can cause Deno to resend a POST on a reused connection. The server receives the body twice. The same script sends it once on Node.js.

The server has already received the first POST before the timeout. It delays its response; it does not deliberately reset the connection. The script calls `http.request()` once per body and has no application retry logic or external dependencies.

### Reproduction

Save as `repro.mjs`:

```js
import assert from "node:assert/strict";
import http from "node:http";
import { setTimeout as delay } from "node:timers/promises";

const keepAlive = !process.argv.includes("--no-keep-alive");
const agent = new http.Agent({ keepAlive });
const received = [];
const server = http.createServer(async (req, res) => {
  const chunks = [];
  for await (const chunk of req) chunks.push(chunk);
  const body = Buffer.concat(chunks).toString();
  received.push(body);
  if (body === "timeout") await delay(500);
  res.end("ok");
});
await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
const url = `http://127.0.0.1:${server.address().port}`;

function post(body, timeout = 0) {
  return new Promise((resolve, reject) => {
    const req = http.request(url, {
      method: "POST",
      agent,
      headers: { "Content-Length": Buffer.byteLength(body) },
    }, (res) => {
      res.resume();
      res.on("end", resolve);
    });
    req.on("error", reject);
    if (timeout) {
      req.setTimeout(timeout, () => {
        console.log(`destroy: reusedSocket=${req.reusedSocket}`);
        req.destroy(new Error("intentional timeout"));
      });
    }
    req.end(body);
  });
}

const deadline = setTimeout(() => {
  console.error("Reproduction exceeded 10 seconds");
  process.exit(2);
}, 10000);
try {
  await post("warmup");
  await delay(20); // Allow the warmup socket to return to the agent pool.
  const outcome = await post("timeout", 100).then(
    () => "resolved",
    (error) => error.message,
  );
  console.log(`outcome: ${outcome}`);
  await delay(700); // Observe any request sent after cancellation.
  console.log(JSON.stringify({ keepAlive, received }));
  assert.deepEqual(received, ["warmup", "timeout"]);
} finally {
  agent.destroy();
  server.closeAllConnections();
  await new Promise((resolve) => server.close(resolve));
  clearTimeout(deadline);
}
